import ProtectedRoute from "../../../components/ProtectedRoute.jsx";
import PageShell from "../../../components/ui/PageShell";
import PresentationDeck from "../../../components/presentation/PresentationDeck";
import presentation from "../../../data/presentation.json";

/**
 * Release Notes — the Super-Admin surface for walking someone through what
 * shipped in a date window, driven from a keyboard on a TV.
 *
 * The data is generated by `pnpm presentation` and committed; this page makes
 * no network call of its own (ADR 0022). Re-run the generator before
 * presenting, or the roadmap shows the state it had when it was last built.
 */
export default function ReleaseNotesPage() {
  return (
    <ProtectedRoute requireSuperAdmin={true}>
      <PageShell title="Release Notes" description={presentation.title}>
        <PresentationDeck data={presentation} />
      </PageShell>
    </ProtectedRoute>
  );
}
